# WAR ARENA - Add local .env loader (zero-dependency) - Installer
# Fixes: server did not read .env locally (vars showed as unset).
# Now a tiny loader reads .env for local runs; no-op on hosted envs (Koyeb).
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-dotenv.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - .env loader installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/deploy/server.ts" ""

Write-Host ""; Write-Host "Building ..." -ForegroundColor Cyan
npm run build; if ($LASTEXITCODE -ne 0){ throw "build failed" }
Write-Host ""; Write-Host ".env loader installed + built. Run: npm start" -ForegroundColor Green
Write-Host "You should now see telegramBotToken:set in the startup log." -ForegroundColor Yellow
